/**
 * Script wordmark for "tigawanna".
 * Font: Aguafina Script regular. The outline is a filled glyph, so the
 * signature animation reveals that fill with a pen stroke along the contours.
 */

/** Leftmost x in a contour, used to write the signature left to right. */
function contourMinX(d: string): number {
  let min = Number.POSITIVE_INFINITY
  for (const match of d.matchAll(/(-?\d*\.?\d+)\s+(-?\d*\.?\d+)/g)) {
    const x = Number(match[1])
    if (x < min) min = x
  }
  return min
}

