const WORDMARK_CONTOURS = WORDMARK_PATH.split(/(?=M)/)
  .filter((contour) => contour.length > 0)
  .sort((a, b) => contourMinX(a) - contourMinX(b))

/** Glyph bounds plus room for the 2.75 pen stroke. */
const VIEW_BOX = { x: -1.5, y: 17.85, width: 155.35, height: 38.85 } as const

const SIGNATURE_DURATION = 2.6
const CONTOUR_DRAW = 0.34
const CONTOUR_STAGGER =
  (SIGNATURE_DURATION - CONTOUR_DRAW) / Math.max(WORDMARK_CONTOURS.length - 1, 1)
const SIGNATURE_HOLD = 1.1
const SIGNATURE_CLEAR = 0.4
const SIGNATURE_CYCLE = SIGNATURE_DURATION + SIGNATURE_HOLD + SIGNATURE_CLEAR

/** Percent stops for one contour inside the full write → hold → clear cycle. */
function loopKeyframes(name: string, index: number): string {
  const start = ((index * CONTOUR_STAGGER) / SIGNATURE_CYCLE) * 100
  const drawn = ((index * CONTOUR_STAGGER + CONTOUR_DRAW) / SIGNATURE_CYCLE) * 100
  const hold = ((SIGNATURE_DURATION + SIGNATURE_HOLD) / SIGNATURE_CYCLE) * 100
  const faded = hold + (SIGNATURE_CLEAR / SIGNATURE_CYCLE) * 80
  const pct = (value: number) => value.toFixed(2)
  const hiddenUntil =
    start > 0.08 ? `0%,${pct(start - 0.05)}%{stroke-dashoffset:100;opacity:0}` : ''
  const filled =
    hold - drawn > 0.2
      ? `${pct(drawn)}%,${pct(hold)}%{stroke-dashoffset:0;opacity:1}`
      : `${pct(hold)}%{stroke-dashoffset:0;opacity:1}`

  return `@keyframes ${name}{${hiddenUntil}${pct(start)}%{stroke-dashoffset:100;opacity:1}${filled}${pct(faded)}%{stroke-dashoffset:0;opacity:0}100%{stroke-dashoffset:100;opacity:0}}`
}

interface TextToSvgComponentProps extends React.SVGProps<SVGSVGElement> {
  className?: string
  style?: React.CSSProperties
  fill?: string
  width?: string | number
  height?: string | number
  /** Play the signature once. Omitted or false leaves the wordmark still. */
  animate?: boolean
  /** Replay the signature after each pass. Only applies when `animate` is set. */
  loop?: boolean
}

export function TigawannaComponent({
  className = '',
  style = {},
  fill = 'currentColor',
  width,
  height,
  animate = false,
  loop = false,
  ...props
}: TextToSvgComponentProps) {
  const maskId = useId().replace(/:/g, '')
  const playing = animate
  const replaying = playing && loop

  return (
    <svg
      className={twMerge('w-[min(92vw,42rem)] text-primary', className)}
      style={style}
      width={width}
      height={height}
      viewBox={`${VIEW_BOX.x} ${VIEW_BOX.y} ${VIEW_BOX.width} ${VIEW_BOX.height}`}
      data-asc="0.966"
      {...props}
    >
      {playing ? (
        <>
          <style>
            {`${WORDMARK_CONTOURS.map((_, index) =>
              loopKeyframes(`tigawanna-write-${maskId}-${index}`, index),
            ).join('')}
@keyframes tigawanna-write-once{
  from{stroke-dashoffset:100;opacity:1}
  to{stroke-dashoffset:0;opacity:1}
}
@media (prefers-reduced-motion: reduce){
  .tigawanna-pen{animation:none !important;stroke-dashoffset:0 !important;opacity:1 !important}
}`}
          </style>
          <defs>
            <mask id={maskId} maskUnits="userSpaceOnUse" {...VIEW_BOX}>
              {WORDMARK_CONTOURS.map((contour, index) => (
                <path
                  key={contour}
                  className="tigawanna-pen"
                  d={contour}
                  fill="none"
                  stroke="white"
                  strokeWidth={2.75}
                  strokeLinecap="butt"
                  strokeLinejoin="round"
                  pathLength={100}
                  style={{
                    strokeDasharray: 100,
                    strokeDashoffset: 100,
                    opacity: 0,
                    animation: replaying
                      ? `tigawanna-write-${maskId}-${index} ${SIGNATURE_CYCLE}s linear infinite`
                      : `tigawanna-write-once ${CONTOUR_DRAW}s cubic-bezier(0.42, 0.02, 0.18, 1) forwards`,
                    animationDelay: replaying ? undefined : `${index * CONTOUR_STAGGER}s`,
                  }}
                />
              ))}
            </mask>
          </defs>
          <path d={WORDMARK_PATH} fill={fill} mask={`url(#${maskId})`} />
        </>
      ) : (
        <path d={WORDMARK_PATH} fill={fill} />
      )}
    </svg>
  )
}


